<?php
require_once __DIR__ . '/../Config/koneksi.php'; require_once __DIR__ . '/../Config/auth.php'; madin_role_required('admin'); require_once __DIR__ . '/_layout.php';
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  madin_csrf_check(); $action=(string)($_POST['action']??'');
  if($action==='delete'){
    $id=(int)($_POST['id_produk']??0); $stmt=mysqli_prepare($conn,"UPDATE produk SET status_produk='nonaktif' WHERE id_produk=?"); mysqli_stmt_bind_param($stmt,'i',$id); $ok=mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt);
    header('Location: produk.php?msg='.rawurlencode($ok?'Produk dinonaktifkan.':'Produk gagal diubah.')); exit;
  }
  if($action==='save'){
    $id=(int)($_POST['id_produk']??0); $nama=trim((string)($_POST['nama_produk']??'')); $deskripsi=trim((string)($_POST['deskripsi']??'')); $harga=(float)($_POST['harga']??0); $stok=max(0,(int)($_POST['stok']??0)); $kategori=(int)($_POST['id_kategori']??0); $foto=trim((string)($_POST['foto']??'')); $status=(string)($_POST['status_produk']??'tersedia');
    if($nama===''||$harga<0||!in_array($status,['tersedia','habis','nonaktif'],true)) $error='Nama, harga, atau status produk tidak valid.';
    else { $katNull=$kategori>0?$kategori:null; if($id>0){$stmt=mysqli_prepare($conn,'UPDATE produk SET id_kategori=?,nama_produk=?,deskripsi=?,harga=?,stok=?,foto=?,status_produk=? WHERE id_produk=?'); mysqli_stmt_bind_param($stmt,'issdissi',$katNull,$nama,$deskripsi,$harga,$stok,$foto,$status,$id);} else {$stmt=mysqli_prepare($conn,'INSERT INTO produk (id_kategori,nama_produk,deskripsi,harga,stok,foto,status_produk) VALUES (?,?,?,?,?,?,?)'); mysqli_stmt_bind_param($stmt,'issdiss',$katNull,$nama,$deskripsi,$harga,$stok,$foto,$status);} $ok=mysqli_stmt_execute($stmt); $dbErr=mysqli_stmt_error($stmt); mysqli_stmt_close($stmt); if($ok){header('Location: produk.php?msg='.rawurlencode($id?'Produk berhasil diperbarui.':'Produk berhasil ditambahkan.'));exit;} $error='Produk gagal disimpan: '.$dbErr; }
  }
}
$edit=null; if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$stmt=mysqli_prepare($conn,'SELECT * FROM produk WHERE id_produk=? LIMIT 1');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$edit=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);}
$cats=mysqli_query($conn,'SELECT id_kategori,nama_kategori FROM kategori ORDER BY nama_kategori'); $q=trim((string)($_GET['q']??'')); $search='%'.$q.'%';$stmt=mysqli_prepare($conn,'SELECT p.*,k.nama_kategori FROM produk p LEFT JOIN kategori k ON k.id_kategori=p.id_kategori WHERE p.nama_produk LIKE ? ORDER BY p.dibuat_pada DESC');mysqli_stmt_bind_param($stmt,'s',$search);mysqli_stmt_execute($stmt);$products=mysqli_stmt_get_result($stmt);
madin_admin_header('Manajemen Produk','produk'); if($error): ?><div class="notice error"><?= madin_e($error) ?></div><?php endif; ?>
<div class="admin-card"><h2><?= $edit?'Edit produk':'Tambah produk' ?></h2><form class="admin-form" method="post"><input type="hidden" name="csrf_token" value="<?= madin_e(madin_csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id_produk" value="<?= (int)($edit['id_produk']??0) ?>"><div class="field"><label>Nama produk *</label><input name="nama_produk" required maxlength="150" value="<?= madin_e($edit['nama_produk']??'') ?>"></div><div class="field"><label>Kategori</label><select name="id_kategori"><option value="0">Tanpa kategori</option><?php if($cats): while($cat=mysqli_fetch_assoc($cats)): ?><option value="<?= (int)$cat['id_kategori'] ?>" <?= (int)($edit['id_kategori']??0)===(int)$cat['id_kategori']?'selected':'' ?>><?= madin_e($cat['nama_kategori']) ?></option><?php endwhile; endif; ?></select></div><div class="field"><label>Harga (Rp) *</label><input type="number" name="harga" min="0" step="1" required value="<?= madin_e($edit['harga']??'0') ?>"></div><div class="field"><label>Stok</label><input type="number" name="stok" min="0" step="1" value="<?= madin_e($edit['stok']??'0') ?>"></div><div class="field"><label>Status</label><select name="status_produk"><?php foreach(['tersedia','habis','nonaktif'] as $st): ?><option value="<?= $st ?>" <?= ($edit['status_produk']??'tersedia')===$st?'selected':'' ?>><?= madin_e(madin_status_label($st)) ?></option><?php endforeach; ?></select></div><div class="field"><label>Path foto (opsional)</label><input name="foto" placeholder="contoh: image 33.png atau uploads/produk.jpg" value="<?= madin_e($edit['foto']??'') ?>"></div><div class="field full"><label>Deskripsi</label><textarea name="deskripsi"><?= madin_e($edit['deskripsi']??'') ?></textarea></div><div class="form-actions"><button class="btn" type="submit">Simpan produk</button><?php if($edit): ?><a class="btn secondary" href="produk.php">Batal edit</a><?php endif; ?></div></form></div>
<div class="admin-card"><h2>Daftar produk</h2><form class="filter-row" method="get"><input name="q" placeholder="Cari nama produk..." value="<?= madin_e($q) ?>"><button class="btn" type="submit">Cari</button><a class="btn secondary" href="produk.php">Reset</a></form><table class="admin-table"><thead><tr><th>Nama</th><th>Kategori</th><th>Stok</th><th>Harga</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if(mysqli_num_rows($products)):while($p=mysqli_fetch_assoc($products)): ?><tr><td><strong><?= madin_e($p['nama_produk']) ?></strong><br><small><?= madin_e(mb_strimwidth((string)$p['deskripsi'],0,85,'…')) ?></small></td><td><?= madin_e($p['nama_kategori']??'—') ?></td><td><?= (int)$p['stok'] ?></td><td><?= madin_money($p['harga']) ?></td><td><span class="status-pill <?= $p['status_produk']==='tersedia'?'ok':($p['status_produk']==='habis'?'warn':'bad') ?>"><?= madin_e(madin_status_label($p['status_produk'])) ?></span></td><td><div class="table-actions"><a class="btn-small secondary" href="produk.php?edit=<?= (int)$p['id_produk'] ?>">Edit</a><?php if($p['status_produk']!=='nonaktif'): ?><form method="post" onsubmit="return confirm('Nonaktifkan produk ini?')"><input type="hidden" name="csrf_token" value="<?= madin_e(madin_csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id_produk" value="<?= (int)$p['id_produk'] ?>"><button class="btn-small danger" type="submit">Nonaktifkan</button></form><?php endif; ?></div></td></tr><?php endwhile;else: ?><tr><td colspan="6" class="empty-state">Produk tidak ditemukan.</td></tr><?php endif; ?></tbody></table></div>
<?php mysqli_stmt_close($stmt); madin_admin_footer(); ?>
